import * as React from 'react';
import { cn } from '@/lib/utils';

export type ButtonGroupProps = React.HTMLAttributes<HTMLDivElement> & {
  /** Stacked segments share vertical edges (default: side-by-side). */
  orientation?: 'horizontal' | 'vertical';
};

/**
 * Joins buttons into one segmented control.
 *
 * The group owns the outline: a single border, one outer radius (children
 * are clipped by overflow-hidden), and 1px separators drawn between
 * segments. Children lose their own borders and radii, so mixed variants
 * (default/outline/secondary/ghost) still read as one instrument — a
 * borderless variant no longer leaves the seam misaligned the way
 * negative-margin border collapsing did.
 *
 * Focus rings render inset so they are never clipped at the edges.
 */
const ButtonGroup = React.forwardRef<HTMLDivElement, ButtonGroupProps>(
  ({ orientation = 'horizontal', className, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="button-group"
      role="group"
      className={cn(
        'inline-flex overflow-hidden rounded-md border border-border bg-background',
        '[&>*]:rounded-none [&>*]:border-0',
        '[&>*:focus-visible]:ring-inset [&>*:focus-visible]:ring-offset-0',
        // divide-* compiles to `.group > * ~ * { border-left/top }` — higher
        // specificity than the lead-strip above, so seams stay exact.
        orientation === 'horizontal'
          ? 'divide-x divide-border'
          : 'flex-col divide-y divide-border',
        className
      )}
      {...props}
    />
  )
);
ButtonGroup.displayName = 'ButtonGroup';

export { ButtonGroup };

{
  "id": "button-group",
  "name": "ButtonGroup",
  "tier": "molecule",
  "description": "Joins buttons into one segmented control: adjacent borders collapse, middle corners square off, and only the outer corners stay rounded — a single outline around the group.",
  "designIntent": "Related actions (view modes, zoom, toolbar steps) should read as one instrument, not scattered pills. ButtonGroup collapses adjacent borders with negative spacing so the joined outline matches InputGroup's single-border language, while focus rings lift above siblings instead of being clipped.",
  "props": [
    {
      "name": "orientation",
      "type": "'horizontal' | 'vertical'",
      "required": false,
      "description": "Stacked segments share vertical edges; default lays them side by side.",
      "defaultValue": "horizontal",
      "examples": [
        "horizontal",
        "vertical"
      ]
    }
  ],
  "examples": [
    {
      "title": "View mode toggle",
      "code": "<ButtonGroup aria-label=\"View mode\">\n  <Button variant=\"outline\">List</Button>\n  <Button variant=\"outline\">Board</Button>\n  <Button variant=\"outline\">Calendar</Button>\n</ButtonGroup>",
      "description": "Three segments share one outline; aria-label names the group."
    },
    {
      "title": "Vertical toolbar steps",
      "code": "<ButtonGroup orientation=\"vertical\" aria-label=\"Step navigation\">\n  <Button variant=\"secondary\">Step back</Button>\n  <Button variant=\"secondary\">Step forward</Button>\n</ButtonGroup>",
      "description": "Stacked segments share horizontal edges."
    },
    {
      "title": "Stepper with primary action",
      "code": "<ButtonGroup aria-label=\"Pagination steps\">\n  <Button variant=\"outline\">Previous</Button>\n  <Button>Next</Button>\n</ButtonGroup>",
      "description": "Mix variants freely as long as each button keeps a border."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use borderless variants inside",
      "explanation": "Ghost/link buttons carry no border, so the joined outline breaks at that segment. The group's single-outline promise depends on every segment contributing an edge.",
      "example": "// Avoid: ghost has no border\n<ButtonGroup><Button variant=\"ghost\">A</Button><Button>B</Button></ButtonGroup>\n\n// Prefer: bordered variants\n<ButtonGroup><Button variant=\"outline\">A</Button><Button variant=\"outline\">B</Button></ButtonGroup>"
    },
    {
      "title": "Don't group unrelated actions",
      "explanation": "A joined outline asserts the segments are alternatives of one control. unrelated actions should stay separate Buttons so their relationship isn't overstated.",
      "example": "// Avoid: Save and Delete as joined segments\n<ButtonGroup><Button>Save</Button><Button variant=\"destructive\">Delete</Button></ButtonGroup>\n\n// Prefer: separate buttons\n<Button>Save</Button>\n<Button variant=\"destructive\">Delete</Button>"
    }
  ],
  "accessibility": [
    {
      "feature": "Group semantics",
      "implementation": "Renders role=group; pass aria-label (or aria-labelledby) so the group name is announced before its buttons",
      "userRequirements": "Always provide an accessible name for the group"
    },
    {
      "feature": "Focus visibility",
      "implementation": "Focused segments get position:relative + z-10 so the ring paints above neighbours instead of clipping",
      "userRequirements": "Don't override with overflow:hidden on the group"
    },
    {
      "feature": "Keyboard order",
      "implementation": "Buttons keep native tab order; groups are not roving-tabindex widgets (use Tabs for that pattern)",
      "userRequirements": "When segments behave like exclusive views, prefer Tabs/segmented semantics"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Segment labels",
      "guidelines": [
        "Use parallel phrasing across segments",
        "Keep labels short enough for one line",
        "Lead with the noun or verb consistently (don't mix)"
      ],
      "goodExamples": [
        "List",
        "Board",
        "Calendar",
        [
          "−",
          "+"
        ]
      ],
      "badExamples": [
        "Show as list",
        "Calendar view now"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Button",
      "relationship": "Direct children — each keeps its own variant/size but must keep a border",
      "example": "<ButtonGroup><Button variant=\"outline\">One</Button><Button variant=\"outline\">Two</Button></ButtonGroup>"
    },
    {
      "component": "Tabs",
      "relationship": "For exclusive views with panels, use Tabs; ButtonGroup is for actions/tools, not view switching with content",
      "example": "<Tabs>…</Tabs>"
    }
  ],
  "relatedComponents": [
    "Button",
    "Tabs",
    "Toolbar"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.7.0",
  "sourceDir": "button-group",
  "exportName": "ButtonGroup"
}
